import{_ as i}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as a,c as n,o,ag as t,G as r}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const E=JSON.parse('{"title":"Cindy getting started: put Claude Code, Codex and Pi in one workspace","description":"Cindy is an open-source AI agent app for desktop and phone. It puts three agent engines, Claude Code, Codex and Pi, in one interface, so that tasks, memory and skills follow you across computers and phones. This page walks you through installing it, running a first task in 10 minutes, and telling which data stays on your machine and which is sent out.","frontmatter":{"title":"Cindy getting started: put Claude Code, Codex and Pi in one workspace","description":"Cindy is an open-source AI agent app for desktop and phone. It puts three agent engines, Claude Code, Codex and Pi, in one interface, so that tasks, memory and skills follow you across computers and phones. This page walks you through installing it, running a first task in 10 minutes, and telling which data stays on your machine and which is sent out.","domain":"product","tags":["multi-agent","coding-agent","device-link","open-source"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"products/cindy/cindy.md","filePath":"products/cindy/cindy.md","lastUpdated":1795792629000}'),h={name:"products/cindy/cindy.md"};function d(l,e,p,c,k,u){const s=a("DocDiagram");return o(),n("div",null,[e[0]||(e[0]=t("",31)),r(s,{src:"/diagrams/cindy-architecture.en.svg",alt:"This layered architecture diagram answers two questions: after a task leaves your phone or computer, which layers does it pass through before it reaches the agent engine, and which data stays on your computer while which goes to Cindy's services or the model provider? There are four areas. On the left are your devices: the phone and computer B. The phone is only a remote control; no agent runs on it, and it reaches computer A only through the Device Link relay in Cindy's cloud, on whitelisted channels. Computer B can be the controller or the controlled side. In the middle is the Cindy client on computer A, in four layers from top to bottom: the UI, or Renderer, which only submits intent to the main process; the main process, which holds the input coordinator, the local SQLite database, automations, and chat channels; the session layer, maker-core, where Maker and Session unify the output of the three harnesses into one event stream that returns to the UI; and at the bottom the harness adapters for Claude Code, Codex, Pi, and the plugin engine. Below the adapters is the harness subprocess, which reads and writes files, the browser, and apps on computer A; project files stay on the computer that runs the task. At the lower right are the model providers, in four kinds: an existing subscription, an API key, a local model, and Cindy's own model service. A harness's model request first passes through the loopback proxy and protocol bridges, and computer A then sends it straight to the chosen provider; only when Cindy's model service is chosen does the request pass through the cloud gateway. At the top is Cindy's cloud, and only four lines connect it to your machine. First, device information and the online heartbeat, sent from the computer to the cloud in sign-in mode only. Second, usage statistics sent to TapDB, on by default and possible to turn off. Third, the conversation sync of cloud companions, which is two-way. Fourth, model requests when Cindy's model service is chosen. In local mode, when sign-in is skipped, there is no heartbeat, no usage reporting, and no Device Link. Agent-Net is a Beta feature, off by default, drawn as an optional encrypted path next to the Device Link relay. This diagram leaves out the server's internal modules, because the backend is not in the open-source repository. It draws no conclusion about whether the official relay reads data, and it shows no prices or quotas.",width:1080,lang:"en"}),e[1]||(e[1]=t("",118))])}const b=i(h,[["render",d]]);export{E as __pageData,b as default};
